package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct {
	DrItem  string          // PIC X(6) @0 len=6
	DrPrice decimal.Decimal // PIC 9(5)V99 @6 len=7
	DrPct   int64           // PIC 9(2) @13 len=2
}

var WsEofFlag string         // PIC X len=1 = "N"
var WsDiscount decimal.Decimal // PIC 9(5)V99 len=7 = 0
var WsNet decimal.Decimal     // PIC 9(5)V99 len=7 = 0
var WsTotalNet decimal.Decimal // PIC 9(8)V99 len=10 = 0
var WsCount int64               // PIC 9(3) len=3 = 0
var WsPriceEd string            // PIC ZZ,ZZ9.99 len=9
var WsDiscEd string             // PIC ZZ,ZZ9.99 len=9
var WsNetEd string              // PIC ZZ,ZZ9.99 len=9
var WsTotalEd string            // PIC ZZ,ZZZ,ZZ9.99 len=13

var discRec DiscRec
var discLines []string
var discIndex int

func pow10Decimal(n int) decimal.Decimal {
	return decimal.New(1, int32(n))
}

func clipDecimal(d decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// d is already at correct scale (truncated/rounded)
	// keep low-order intDigits
	if intDigits <= 0 {
		// only fractional?
		return d
	}
	// for non-negative values
	if d.IsNegative() {
		// not expected for this program, but handle symmetric
		neg := true
		ad := d.Abs()
		intPart := ad.Truncate(0)
		frac := ad.Sub(intPart)
		mod := pow10Decimal(intDigits)
		// decimal Mod for positive
		intPartMod := intPart.Mod(mod)
		res := intPartMod.Add(frac)
		if neg {
			res = res.Neg()
		}
		// ensure scale
		return res.Truncate(scale)
	}
	intPart := d.Truncate(0)
	frac := d.Sub(intPart)
	mod := pow10Decimal(intDigits)
	// if intPart < mod, Mod returns intPart; else remainder
	intPartMod := intPart.Mod(mod)
	res := intPartMod.Add(frac)
	return res
}

func storePic9V99(d decimal.Decimal, intDigits int, scale int32, rounded bool) decimal.Decimal {
	var v decimal.Decimal
	if rounded {
		v = d.Round(scale)
	} else {
		v = d.Truncate(scale)
	}
	v = clipDecimal(v, intDigits, scale)
	// ensure truncated to scale (clip may have produced scale correctly)
	v = v.Truncate(scale)
	return v
}

func formatIntPic9(v int64, digits int) string {
	if digits <= 0 {
		return ""
	}
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	// handle negative? not needed
	mv := v % mod
	if mv < 0 {
		mv = -mv
	}
	return fmt.Sprintf("%0*d", digits, mv)
}

func formatEdited(d decimal.Decimal, picture string) string {
	dotPos := strings.Index(picture, ".")
	var intPicPart string
	var decDigits int
	if dotPos >= 0 {
		intPicPart = picture[:dotPos]
		decPart := picture[dotPos+1:]
		// count 9/Z in dec part (should be all 9)
		for _, ch := range decPart {
			if ch == 'Z' || ch == '9' {
				decDigits++
			}
		}
	} else {
		intPicPart = picture
		decDigits = 0
	}
	// count integer digit slots
	intDigits := 0
	for _, ch := range intPicPart {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	// collect positions
	picRunes := []rune(picture)
	out := make([]rune, len(picRunes))
	copy(out, picRunes)

	// integer positions indices in picture
	var intPositions []int
	for i, ch := range picRunes {
		if dotPos >= 0 && i > dotPos {
			continue
		}
		if dotPos >= 0 && i == dotPos {
			continue
		}
		if ch == 'Z' || ch == '9' {
			intPositions = append(intPositions, i)
		}
	}
	var decPositions []int
	if dotPos >= 0 {
		for i, ch := range picRunes {
			if i > dotPos && (ch == 'Z' || ch == '9') {
				decPositions = append(decPositions, i)
			}
		}
	}

	abs := d.Abs()
	// ensure scale handling
	// int part
	intPartDec := abs.Truncate(0)
	fracDec := abs.Sub(intPartDec)

	// fractional integer value
	var fracInt int64
	if decDigits > 0 {
		shifted := fracDec.Shift(int32(decDigits)).Truncate(0)
		fracInt = shifted.IntPart()
		if fracInt < 0 {
			fracInt = -fracInt
		}
	}

	// integer part modulo 10^intDigits for picture overflow rule
	var intMod decimal.Decimal
	if intDigits > 0 {
		mod := pow10Decimal(intDigits)
		intMod = intPartDec.Mod(mod)
	} else {
		intMod = decimal.NewFromInt(0)
	}
	intVal := intMod.IntPart()
	if intVal < 0 {
		intVal = -intVal
	}
	intStr := fmt.Sprintf("%0*d", intDigits, intVal)

	// fill integer digits
	for idx, pos := range intPositions {
		if idx < len(intStr) {
			out[pos] = rune(intStr[idx])
		}
	}
	// fill decimal digits
	if decDigits > 0 {
		decStr := fmt.Sprintf("%0*d", decDigits, fracInt)
		for idx, pos := range decPositions {
			if idx < len(decStr) {
				out[pos] = rune(decStr[idx])
			}
		}
	}

	// suppression for Z
	seenNonZero := false
	for _, pos := range intPositions {
		chPic := picRunes[pos]
		dig := out[pos]
		if dig != '0' && dig != ' ' {
			seenNonZero = true
		}
		if chPic == 'Z' && !seenNonZero && dig == '0' {
			out[pos] = ' '
		} else {
			if dig != '0' {
				// already set seen, nothing
			} else {
				// dig == '0' but either seenNonZero true or chPic == '9' keep
				// ensure seen stays false if still zero and not seen? but 9 zero doesn't make seen
				// keep as is
			}
			// update seen for next iteration if this digit was non-zero
			if dig != '0' && dig != ' ' {
				seenNonZero = true
			}
		}
		// Need to update seenNonZero correctly: if dig is not '0' and not ' ' then mark
		// For '0' kept (either Z with seen true or 9) we do not become non-zero
	}

	// commas become spaces if all integer positions to left are spaces
	for i, ch := range picRunes {
		if ch == ',' {
			allSpacesLeft := true
			for _, p := range intPositions {
				if p < i {
					if out[p] != ' ' {
						allSpacesLeft = false
						break
					}
				}
			}
			if allSpacesLeft {
				out[i] = ' '
			} else {
				out[i] = ','
			}
		}
		if ch == '.' {
			out[i] = '.'
		}
	}

	return string(out)
}

func parseDigitsToDecimal(s string, scale int32) decimal.Decimal {
	trim := strings.TrimSpace(s)
	if trim == "" {
		return decimal.NewFromInt(0)
	}
	// keep only digits, ignore other chars? But spec digits only
	// If contains spaces, treat as zero?
	// Remove leading zeros but parse
	// Use decimal from string then shift
	// s may contain only digits
	d, err := decimal.NewFromString(trim)
	if err != nil {
		// try to extract digits
		var b strings.Builder
		for _, r := range trim {
			if r >= '0' && r <= '9' {
				b.WriteRune(r)
			}
		}
		if b.Len() == 0 {
			return decimal.NewFromInt(0)
		}
		d, _ = decimal.NewFromString(b.String())
	}
	return d.Shift(-scale)
}

func parseInt64FromField(s string) int64 {
	trim := strings.TrimSpace(s)
	if trim == "" {
		return 0
	}
	var b strings.Builder
	for _, r := range trim {
		if r >= '0' && r <= '9' {
			b.WriteRune(r)
		}
	}
	if b.Len() == 0 {
		return 0
	}
	var v int64
	fmt.Sscan(b.String(), &v)
	return v
}

func loadDiscFile() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		// if file not exists, treat as empty
		discLines = []string{}
		return
	}
	// Use bufio.Scanner to handle lines correctly preserving spaces (except newline)
	// Scanner strips \r and \n but we need to keep other spaces
	// We'll use scanner
	var lines []string
	scanner := bufio.NewScanner(strings.NewReader(string(data)))
	// Increase buffer for long lines
	buf := make([]byte, 0, 1024*1024)
	scanner.Buffer(buf, 10*1024*1024)
	for scanner.Scan() {
		line := scanner.Text()
		// scanner.Text() strips \r and \n, but retains other spaces
		// Note: it strips trailing \r for CRLF
		lines = append(lines, line)
	}
	// If file ends with newline, scanner does not produce extra empty record, which is correct
	discLines = lines
}

func padRight(s string, length int) string {
	if len(s) >= length {
		if len(s) > length {
			return s[:length]
		}
		return s
	}
	return s + strings.Repeat(" ", length-len(s))
}

func READ_PARA() {
	if discIndex >= len(discLines) {
		WsEofFlag = "Y"
		return
	}
	raw := discLines[discIndex]
	discIndex++
	// pad to 15
	rec := padRight(raw, 15)
	// offsets
	drItem := rec[0:6]
	drPriceField := rec[6:13]  // 7 chars
	drPctField := rec[13:15] // 2 chars

	discRec.DrItem = drItem
	discRec.DrPrice = parseDigitsToDecimal(drPriceField, 2)
	discRec.DrPct = parseInt64FromField(drPctField)
}

func PROCESS_PARA() {
	// COMPUTE WS-DISCOUNT ROUNDED = DR-PRICE * DR-PCT / 100
	prod := discRec.DrPrice.Mul(decimal.NewFromInt(discRec.DrPct))
	divisor := prod.Shift(-2) // divide by 100
	WsDiscount = storePic9V99(divisor, 5, 2, true)

	// COMPUTE WS-NET = DR-PRICE - WS-DISCOUNT
	diff := discRec.DrPrice.Sub(WsDiscount)
	WsNet = storePic9V99(diff, 5, 2, false)

	// ADD WS-NET TO WS-TOTAL-NET
	sum := WsTotalNet.Add(WsNet)
	WsTotalNet = storePic9V99(sum, 8, 2, false)

	// ADD 1 TO WS-COUNT
	WsCount = WsCount + 1
	// clip to 3 digits
	if WsCount >= 1000 {
		WsCount = WsCount % 1000
	}

	WsPriceEd = formatEdited(discRec.DrPrice, "ZZ,ZZ9.99")
	WsDiscEd = formatEdited(WsDiscount, "ZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZ,ZZ9.99")

	// DISPLAY
	pctStr := formatIntPic9(discRec.DrPct, 2)
	// DR-ITEM is exactly 6 chars, WsPriceEd 9, etc.
	// Per COBOL DISPLAY concatenates with no extra padding beyond fields
	fmt.Printf("%s %s %s%% %s %s\n", discRec.DrItem, WsPriceEd, pctStr, WsDiscEd, WsNetEd)

	READ_PARA()
}

func SUMMARY_PARA() {
	WsTotalEd = formatEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	countStr := formatIntPic9(WsCount, 3)
	fmt.Printf("ITEMS: %s NET TOTAL: %s\n", countStr, WsTotalEd)
}

func main() {
	WsEofFlag = "N"
	WsDiscount = decimal.NewFromInt(0)
	WsNet = decimal.NewFromInt(0)
	WsTotalNet = decimal.NewFromInt(0)
	WsCount = 0

	loadDiscFile()
	discIndex = 0

	READ_PARA()
	for WsEofFlag != "Y" {
		PROCESS_PARA()
	}
	SUMMARY_PARA()
}

